CREATE TABLE IF NOT EXISTS cases (id TEXT PRIMARY KEY, ip_name TEXT NOT NULL, brand_name TEXT NOT NULL, brand_industry TEXT NOT NULL DEFAULT '', cooperation_date TEXT NOT NULL DEFAULT '', cooperation_form TEXT NOT NULL DEFAULT '', product_content TEXT NOT NULL DEFAULT '', merchandising TEXT NOT NULL DEFAULT '', activity_play TEXT NOT NULL DEFAULT '', highlights TEXT NOT NULL DEFAULT '', reference_value TEXT NOT NULL DEFAULT '', official_url TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', ip_type TEXT NOT NULL DEFAULT '', ip_intro TEXT NOT NULL DEFAULT '', brand_intro TEXT NOT NULL DEFAULT '', extra_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS case_images (id TEXT PRIMARY KEY, case_id TEXT NOT NULL, object_key TEXT NOT NULL, file_name TEXT NOT NULL DEFAULT '', content_type TEXT NOT NULL DEFAULT 'image/jpeg', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_items (id TEXT PRIMARY KEY, collection TEXT NOT NULL, item_name TEXT NOT NULL DEFAULT '', payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cases_ip_name ON cases(ip_name);
CREATE INDEX IF NOT EXISTS idx_cases_brand_name ON cases(brand_name);
CREATE INDEX IF NOT EXISTS idx_cases_cooperation_date ON cases(cooperation_date);
CREATE INDEX IF NOT EXISTS idx_library_collection ON library_items(collection);
INSERT OR IGNORE INTO cases (id,ip_name,brand_name,brand_industry,cooperation_date,cooperation_form,product_content,merchandising,activity_play,highlights,reference_value,official_url,tags,ip_type,ip_intro,brand_intro,extra_json,created_at,updated_at) VALUES ('case_seed_1','一人之下','东方墨兰','茶饮','2026年7月30日','IP主题茶饮联名','推出“一人之下”主题限定饮品，将张楚岚、冯宝宝等角色视觉元素融入饮品包装与宣传物料','五人角色专属联名杯、限定杯提、氛围感杯套、专属封口贴纸，椰子香牌、拍立得盲袋、杜邦环保袋、反光角色徽章、主题店限定镭射票，多款联名纸袋与保温袋','购买指定联名饮品获得IP限定物料，通过茶饮消费场景触达粉丝用户','通过“东方茶饮×东方国漫”的调性匹配，将IP文化元素自然融入消费场景，提升联名内容的契合度。','','https://www.xiaohongshu.com/discovery/item/6a63239f000000001d00dd99?source=webshare&xhsshare=pc_web&xsec_token=ABvR4b5gEr2htul6ZyplWlKY-7buKIcJFofOr5ShP75M8=&xsec_source=pc_share','国漫,茶饮','国漫','《一人之下》是阅文旗下具有代表性的国漫IP，以现代都市异人与中国传统文化元素结合为特色，拥有大量年轻粉丝群体。','','{"案例ID":"1","联名双方":"东方墨兰×一人之下","IP名称":"一人之下","IP类型":"国漫","IP授权方":"阅文","品牌名称":"东方墨兰","品牌行业":"茶饮","活动开始时间":"2026年7月30日","活动图片":"=DISPIMG(\"ID_DFDF461BD1CA441798E79B933CDAA642\",1)","合作形式":"IP主题茶饮联名","产品内容":"推出“一人之下”主题限定饮品，将张楚岚、冯宝宝等角色视觉元素融入饮品包装与宣传物料","周边形式":"五人角色专属联名杯、限定杯提、氛围感杯套、专属封口贴纸，椰子香牌、拍立得盲袋、杜邦环保袋、反光角色徽章、主题店限定镭射票，多款联名纸袋与保温袋","活动玩法":"购买指定联名饮品获得IP限定物料，通过茶饮消费场景触达粉丝用户","线下活动（若无，则填无）":"东方墨兰门店主题陈列","官方来源链接":"https://www.xiaohongshu.com/discovery/item/6a63239f000000001d00dd99?source=webshare&xhsshare=pc_web&xsec_token=ABvR4b5gEr2htul6ZyplWlKY-7buKIcJFofOr5ShP75M8=&xsec_source=pc_share","IP简介":"《一人之下》是阅文旗下具有代表性的国漫IP，以现代都市异人与中国传统文化元素结合为特色，拥有大量年轻粉丝群体。","品牌简介":"东方墨兰是新中式茶饮品牌，强调东方美学和年轻消费体验。","合作亮点":"通过“东方茶饮×东方国漫”的调性匹配，将IP文化元素自然融入消费场景，提升联名内容的契合度。"}','2026-08-09T00:00:00.000Z','2026-08-09T00:00:00.000Z');
