INSERT OR IGNORE INTO cases (id,ip_name,brand_name,brand_industry,cooperation_date,cooperation_form,product_content,merchandising,activity_play,highlights,reference_value,official_url,tags,ip_type,ip_intro,brand_intro,extra_json,created_at,updated_at) VALUES ('case_seed_3','全职高手','Goodslove','周边衍生','2026年7月25日','IP授权周边开发','推出《全职高手》香氛类衍生产品，围绕叶修、荣耀电竞等IP元素进行设计','主题空间、线下试香、趣味集章、荣耀回信、打卡赠礼','7月25日起，上海弗止门店化身「荣耀香旅驿站」贩售联名香氛产品；7月30日起，GOODSLOVE全国3家门店同步焕新主题展桌，14家门店设置试香点
 ','依托成熟电竞IP的角色资产，通过收藏型周边实现粉丝经济转化，强化IP商业价值。','','https://www.xiaohongshu.com/discovery/item/6a62d2eb000000000401fc37?source=webshare&xhsshare=pc_web&xsec_token=AB34I3dLzN_PBYFkB6gw1VEG_f8RYlqDTb-bOwo1UYD1A=&xsec_source=pc_share','国漫,周边衍生','国漫','《全职高手》是腾讯动漫代表性国漫IP，围绕电竞竞技、职业成长和团队羁绊展开，具有成熟粉丝基础。','','{"案例ID":"3","联名双方":"Goodslove×弗止x全职高手","IP名称":"全职高手","IP类型":"国漫","IP授权方":"腾讯动漫","品牌名称":"Goodslove","品牌行业":"周边衍生","活动开始时间":"2026年7月25日","活动图片":"=DISPIMG(\"ID_A809BB1364D040FC916CC9C37EA81D8A\",1)","合作形式":"IP授权周边开发","产品内容":"推出《全职高手》香氛类衍生产品，围绕叶修、荣耀电竞等IP元素进行设计","周边形式":"主题空间、线下试香、趣味集章、荣耀回信、打卡赠礼","活动玩法":"7月25日起，上海弗止门店化身「荣耀香旅驿站」贩售联名香氛产品；7月30日起，GOODSLOVE全国3家门店同步焕新主题展桌，14家门店设置试香点\n ","线下活动（若无，则填无）":"上海弗止线下门店；Goodslove线下门店","官方来源链接":"https://www.xiaohongshu.com/discovery/item/6a62d2eb000000000401fc37?source=webshare&xhsshare=pc_web&xsec_token=AB34I3dLzN_PBYFkB6gw1VEG_f8RYlqDTb-bOwo1UYD1A=&xsec_source=pc_share","IP简介":"《全职高手》是腾讯动漫代表性国漫IP，围绕电竞竞技、职业成长和团队羁绊展开，具有成熟粉丝基础。","品牌简介":"Goodslove是动漫游戏衍生品品牌，主要进行IP授权周边开发和粉丝向商品运营。","合作亮点":"依托成熟电竞IP的角色资产，通过收藏型周边实现粉丝经济转化，强化IP商业价值。"}','2026-08-09T00:00:00.000Z','2026-08-09T00:00:00.000Z');
INSERT OR IGNORE INTO cases (id,ip_name,brand_name,brand_industry,cooperation_date,cooperation_form,product_content,merchandising,activity_play,highlights,reference_value,official_url,tags,ip_type,ip_intro,brand_intro,extra_json,created_at,updated_at) VALUES ('case_seed_4','凡人修仙传','上海豫园','文旅','2026年7月3日','IP文旅联动+主题空间+餐饮联名','联动豫园商城“万物有灵游园会”，推出《凡人修仙传》主题体验活动；湖心亭、春风松月楼推出联名餐饮套餐','立牌、吧唧、杯垫、ID卡套、主题纪念物料','游客可参与主题打卡、线下游园体验、购买联名餐饮并领取限定周边','将仙侠世界观植入传统文化空间，通过沉浸式场景、餐饮和周边形成完整IP体验链路。','','https://www.xiaohongshu.com/discovery/item/6a6c66b10000000024024436?source=webshare&xhsshare=pc_web&xsec_token=ABQa2ChR7rJZfPOzq1f3mA0giWAZQ1r7k-_6L8h9PrLbI=&xsec_source=pc_share','国漫,文旅','国漫','《凡人修仙传》改编自起点中文网同名小说，是头部仙侠国漫IP，以韩立成长线、修仙世界观和东方幻想元素为核心。','','{"案例ID":"4","联名双方":"上海豫园×凡人修仙传","IP名称":"凡人修仙传","IP类型":"国漫","IP授权方":"哔哩哔哩","品牌名称":"上海豫园","品牌行业":"文旅","活动开始时间":"2026年7月3日","活动图片":"=DISPIMG(\"ID_C71ACD4195A34F51A173CEC9912EE767\",1)","合作形式":"IP文旅联动+主题空间+餐饮联名","产品内容":"联动豫园商城“万物有灵游园会”，推出《凡人修仙传》主题体验活动；湖心亭、春风松月楼推出联名餐饮套餐","周边形式":"立牌、吧唧、杯垫、ID卡套、主题纪念物料","活动玩法":"游客可参与主题打卡、线下游园体验、购买联名餐饮并领取限定周边","线下活动（若无，则填无）":"上海豫园商城设置主题打卡装置“青竹蜂云剑阵”等IP互动空间","官方来源链接":"https://www.xiaohongshu.com/discovery/item/6a6c66b10000000024024436?source=webshare&xhsshare=pc_web&xsec_token=ABQa2ChR7rJZfPOzq1f3mA0giWAZQ1r7k-_6L8h9PrLbI=&xsec_source=pc_share","IP简介":"《凡人修仙传》改编自起点中文网同名小说，是头部仙侠国漫IP，以韩立成长线、修仙世界观和东方幻想元素为核心。","品牌简介":"上海豫园是上海传统文化商业空间和城市文旅地标，融合商业、文化和旅游消费。","合作亮点":"将仙侠世界观植入传统文化空间，通过沉浸式场景、餐饮和周边形成完整IP体验链路。"}','2026-08-09T00:00:00.000Z','2026-08-09T00:00:00.000Z');
