INSERT OR IGNORE INTO library_items (id,collection,item_name,payload_json,created_at,updated_at) VALUES ('ip_assets_1','ip_assets','凡人修仙传','{"IP名称":"凡人修仙传","IP类型":"国漫","所属公司":"哔哩哔哩/万维猫动画","IP简介":"改编自忘语同名小说的仙侠国漫，讲述普通少年韩立从凡人成长为修仙强者的故事，是头部男频修仙IP代表。","核心题材":"仙侠、修真、成长、冒险","目标用户":"18-35岁男性用户为主","用户画像":"男性向；喜欢东方幻想、升级成长、世界观探索；核心粉丝付费意愿较强","核心角色":"韩立、南宫婉、紫灵","视觉风格":"东方仙侠、写实国风、成熟男性审美","IP关键词":"修仙、成长、逆袭、东方幻想、凡人流","商业化优势":"世界观成熟；男性用户消费能力较强；角色资产稳定","适合授权方向":"3C数码、游戏、茶饮、食品、文创、电竞、珠宝、国风消费","不适合方向":"低客单女性消费、过度幼态化产品","已有合作案例":"库迪×凡人修仙传；迈从×凡人修仙传；致态×凡人修仙传；薇姿×凡人修仙传；上海豫园×凡人修仙传","资料链接":"https://www.bilibili.com"}','2026-08-09T00:00:00.000Z','2026-08-09T00:00:00.000Z');
INSERT OR IGNORE INTO library_items (id,collection,item_name,payload_json,created_at,updated_at) VALUES ('ip_assets_2','ip_assets','剑来','{"IP名称":"剑来","IP类型":"国漫","所属公司":"腾讯动漫","IP简介":"改编自烽火戏诸侯同名小说的东方仙侠国漫，以少年陈平安成长和江湖修行为主线。","核心题材":"仙侠、武侠、东方幻想","目标用户":"18-35岁男性用户","用户画像":"偏好传统文化、武侠、世界观构建，对国风美学接受度高","核心角色":"陈平安、宁姚","视觉风格":"东方水墨、古典山水、国风武侠","IP关键词":"江湖、修行、少年成长、东方美学","商业化优势":"文化属性强；适合打造高审美授权产品","适合授权方向":"非遗文创、茶饮、文旅、国风消费、收藏品","不适合方向":"快消低价、强促销型产品","已有合作案例":"龙虎山木作×剑来；幸运咖×剑来；和平精英×剑来","资料链接":"https://ac.qq.com"}','2026-08-09T00:00:00.000Z','2026-08-09T00:00:00.000Z');
